const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const orgId = () => {
  if (typeof window === "undefined") return null;
  try {
    const s = auth.getSession();
    return s?.organisation?.id && UUID_RE.test(s.organisation.id)
      ? s.organisation.id
      : null;
  } catch {
    return null;
  }
};

