function KpiCard({ icon: Icon, label, value, trend, color, bg, chart }: any) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="stat-card"
    >
      <div className="flex items-start justify-between mb-2">
        <div
          className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0"
          style={{ background: bg, color }}
        >
          <Icon size={18} />
        </div>
        {trend && (
          <Badge
            variant={trend.startsWith("+") ? "success" : "danger"}
            className="text-[9px]"
          >
            {trend}
          </Badge>
        )}
      </div>
      <div className="text-[11px] text-gray-500 font-medium">{label}</div>
      <div className="text-xl font-extrabold text-gray-900 mt-0.5">
        {value ?? "—"}
      </div>
      {chart && chart.length > 0 && (
        <div className="flex items-end gap-0.5 h-6 mt-1">
          {chart.map((v: number, ci: number) => (
            <div
              key={ci}
              className="flex-1 rounded-sm"
              style={{
                height: `${Math.max(v * 0.7, 3)}%`,
                background: `${color}25`,
              }}
            />
          ))}
        </div>
      )}
    </motion.div>
  );
}

function DataTable({
  columns,
  data,
  loading,
  error,
  onRetry,
  onRowClick,
  emptyMessage = "No data found",
}: {
  columns: {
    key: string;
    label: string;
    render?: (val: any, row: any) => any;
  }[];
  data: any[];
  loading: boolean;
  error?: string | null;
  onRetry?: () => void;
  onRowClick?: (row: any) => void;
  emptyMessage?: string;
}) {
  if (loading) return <LoadingSkeleton rows={4} cols={columns.length} />;
  if (error) return <ErrorState message={error} onRetry={onRetry} />;
  if (!data || !Array.isArray(data) || data.length === 0)
    return <EmptyState message={emptyMessage} />;
  return (
    <div className="overflow-x-auto rounded-xl border border-gray-100">
      <table className="data-table">
        <thead>
          <tr>
            {columns.map((col) => (
              <th key={col.key}>{col.label}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {data.map((row, i) => (
            <tr
              key={row.id || i}
              onClick={() => onRowClick?.(row)}
              className={onRowClick ? "cursor-pointer" : ""}
            >
              {columns.map((col) => (
                <td key={col.key}>
                  {col.render
                    ? col.render(row[col.key], row)
                    : (row[col.key] ?? "—")}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

