  const renderChartOfAccounts = () => {
    const items = chartOfAccounts.data?.data || chartOfAccounts.data || [];
    const groups = (Array.isArray(items) ? items : []).reduce(
      (acc: any, a: any) => {
        const g = a.account_group || "Other";
        if (!acc[g]) acc[g] = [];
        acc[g].push(a);
        return acc;
      },
      {},
    );

    const TYPE_COLORS: Record<string, string> = {
      asset: "#22C55E",
      liability: "#EF4444",
      income: "#6D4CFF",
      expense: "#F59E0B",
      equity: "#3B82F6",
    };

    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="text-sm font-semibold text-gray-700">
            Chart of Accounts
          </h3>
          <AddButton
            onClick={() => toast.success("Add account form coming soon")}
            label="Add Account"
          />
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {Object.entries(groups).map(([group, accounts]: [string, any]) => (
            <Card key={group} className="p-4">
              <h4
                className="text-[11px] font-semibold mb-3 capitalize flex items-center gap-2"
                style={{ color: TYPE_COLORS[group] || "#6D4CFF" }}
              >
                <div
                  className="w-2 h-2 rounded-full"
                  style={{ background: TYPE_COLORS[group] || "#6D4CFF" }}
                />{" "}
                {group.replace(/_/g, " ")}
              </h4>
              <div className="space-y-1">
                {accounts.map((a: any) => (
                  <div
                    key={a.id}
                    className="flex items-center justify-between p-1.5 rounded-lg hover:bg-gray-50"
                  >
                    <div>
                      <span className="text-[10px] font-semibold text-gray-700">
                        {a.account_name}
                      </span>
                      <span className="text-[8px] text-gray-400 ml-2">
                        {a.account_code}
                      </span>
                    </div>
                    <span className="text-[10px] font-bold">
                      ${(a.balance || 0).toLocaleString()}
                    </span>
                  </div>
                ))}
              </div>
              <div className="mt-2 pt-2 border-t border-gray-100 flex justify-between text-[10px]">
                <span className="text-gray-400">Total Balance</span>
                <span className="font-bold">
                  $
                  {(
                    accounts.reduce(
                      (s: number, a: any) => s + (a.balance || 0),
                      0,
                    ) / 1000
                  ).toFixed(1)}
                  K
                </span>
              </div>
            </Card>
          ))}
        </div>
        {Object.keys(groups).length === 0 && (
          <EmptyState message="No accounts created yet" />
        )}
      </div>
    );
  };

