function AlumniFormModal({
  open,
  edit,
  onClose,
  onSaved,
}: {
  open: boolean;
  edit: any;
  onClose: () => void;
  onSaved: () => void;
}) {
  const f = useForm(
    edit || {
      full_name: "",
      email: "",
      phone: "",
      graduation_year: "",
      current_occupation: "",
      company: "",
      address: "",
    },
  );
  const [saving, setSaving] = useState(false);
  const fields = [
    { key: "full_name", label: "Full Name", type: "text" },
    { key: "email", label: "Email", type: "text" },
    { key: "phone", label: "Phone", type: "text" },
    { key: "graduation_year", label: "Graduation Year", type: "number" },
    { key: "current_occupation", label: "Occupation", type: "text" },
    { key: "company", label: "Company", type: "text" },
    { key: "address", label: "Address", type: "text" },
  ];
  return (
    <CrudModal
      open={open}
      onClose={onClose}
      title={edit ? "Edit Alumni" : "Add Alumni"}
    >
      <div className="space-y-4">
        {fields.map((field) => (
          <div key={field.key}>
            <label className="text-xs font-semibold text-gray-700 mb-1 block">
              {field.label}
            </label>
            <input
              type={field.type}
              value={f.values[field.key] as string}
              onChange={(e) => f.handleChange(field.key, e.target.value)}
              className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:border-[#6D4CFF]"
            />
          </div>
        ))}
        <button
          disabled={saving}
          onClick={async () => {
            setSaving(true);
            try {
              if (edit) {
                await alumniMgmtApi.update(edit.id, f.values);
                toast.success("Updated");
              } else {
                await alumniMgmtApi.create(f.values);
                toast.success("Created");
              }
              onSaved();
            } catch (e: any) {
              toast.error(e.message);
            } finally {
              setSaving(false);
            }
          }}
          className="w-full py-2.5 rounded-lg bg-gradient-to-r from-[#6D4CFF] to-[#8B5CF6] text-white text-sm font-semibold disabled:opacity-50"
        >
          {saving ? "Saving..." : edit ? "Update" : "Create"}
        </button>
      </div>
    </CrudModal>
  );
}

function AlumniEventFormModal({
  open,
  edit,
  onClose,
  onSaved,
}: {
  open: boolean;
  edit: any;
  onClose: () => void;
  onSaved: () => void;
}) {
  const f = useForm(
    edit || { title: "", description: "", event_date: "", location: "" },
  );
  const [saving, setSaving] = useState(false);
  const fields = [
    { key: "title", label: "Title", type: "text" },
    { key: "description", label: "Description", type: "text" },
    { key: "event_date", label: "Event Date", type: "date" },
    { key: "location", label: "Location", type: "text" },
  ];
  return (
    <CrudModal
      open={open}
      onClose={onClose}
      title={edit ? "Edit Event" : "Add Event"}
    >
      <div className="space-y-4">
        {fields.map((field) => (
          <div key={field.key}>
            <label className="text-xs font-semibold text-gray-700 mb-1 block">
              {field.label}
            </label>
            <input
              type={field.type}
              value={f.values[field.key] as string}
              onChange={(e) => f.handleChange(field.key, e.target.value)}
              className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:border-[#6D4CFF]"
            />
          </div>
        ))}
        <button
          disabled={saving}
          onClick={async () => {
            setSaving(true);
            try {
              if (edit) {
                await alumniMgmtApi.updateEvent(edit.id, f.values);
                toast.success("Updated");
              } else {
                await alumniMgmtApi.createEvent(f.values);
                toast.success("Created");
              }
              onSaved();
            } catch (e: any) {
              toast.error(e.message);
            } finally {
              setSaving(false);
            }
          }}
          className="w-full py-2.5 rounded-lg bg-gradient-to-r from-[#6D4CFF] to-[#8B5CF6] text-white text-sm font-semibold disabled:opacity-50"
        >
          {saving ? "Saving..." : edit ? "Update" : "Create"}
        </button>
      </div>
    </CrudModal>
  );
}

function AlumniDonationFormModal({
  open,
  onClose,
  onSaved,
}: {
  open: boolean;
  onClose: () => void;
  onSaved: () => void;
}) {
  const f = useForm({
    alumni_id: "",
    amount: "",
    purpose: "",
    donation_date: new Date().toISOString().split("T")[0],
  });
  const [alumniList, setAlumniList] = useState<any[]>([]);
  const [saving, setSaving] = useState(false);
  useEffect(() => {
    (async () =>
      setAlumniList(
        await apiClient.safeFetchArray(`/alumni-management/alumni/${orgId()}`),
      ))();
  }, []);
  return (
    <CrudModal open={open} onClose={onClose} title="Add Donation">
      <div className="space-y-4">
        <div>
          <label className="text-xs font-semibold text-gray-700 mb-1 block">
            Alumni
          </label>
          <select
            value={f.values.alumni_id as string}
            onChange={(e) => f.handleChange("alumni_id", e.target.value)}
            className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm bg-white focus:outline-none focus:border-[#6D4CFF]"
          >
            <option value="">Select alumni...</option>
            {alumniList.map((a: any) => (
              <option key={a.id} value={a.id}>
                {a.full_name} ({a.graduation_year})
              </option>
            ))}
          </select>
        </div>
        <div>
          <label className="text-xs font-semibold text-gray-700 mb-1 block">
            Amount (₹)
          </label>
          <input
            type="number"
            value={f.values.amount as string}
            onChange={(e) => f.handleChange("amount", e.target.value)}
            className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:border-[#6D4CFF]"
          />
        </div>
        <div>
          <label className="text-xs font-semibold text-gray-700 mb-1 block">
            Purpose
          </label>
          <input
            type="text"
            value={f.values.purpose as string}
            onChange={(e) => f.handleChange("purpose", e.target.value)}
            className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:border-[#6D4CFF]"
          />
        </div>
        <div>
          <label className="text-xs font-semibold text-gray-700 mb-1 block">
            Date
          </label>
          <input
            type="date"
            value={f.values.donation_date as string}
            onChange={(e) => f.handleChange("donation_date", e.target.value)}
            className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:border-[#6D4CFF]"
          />
        </div>
        <button
          disabled={saving}
          onClick={async () => {
            setSaving(true);
            try {
              await alumniMgmtApi.createDonation(f.values);
              toast.success("Donation recorded");
              onSaved();
            } catch (e: any) {
              toast.error(e.message);
            } finally {
              setSaving(false);
            }
          }}
          className="w-full py-2.5 rounded-lg bg-gradient-to-r from-[#6D4CFF] to-[#8B5CF6] text-white text-sm font-semibold disabled:opacity-50"
        >
          {saving ? "Saving..." : "Record Donation"}
        </button>
      </div>
    </CrudModal>
  );
}

