function AdmissionsWorkspace() {
  const { t, ui } = useLanguage();
  const applications = useApi(() => admissionApi.getApplications(), []);
  const enquiries = useApi(() => admissionApi.getEnquiries(), []);
  const reports = useApi(() => admissionApi.getReports(), []);
  const classes = useApi(() => classApi.getAll(), []);
  const years = useApi(() => academicMgmtApi.getAcademicYears(), []);
  const [view, setView] = useState<"applications" | "enquiries">(
    "applications",
  );
  const [modal, setModal] = useState<"application" | "enquiry" | null>(null);
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState("");
  const appForm = useForm({
    applicant_name: "",
    applicant_email: "",
    phone: "",
    applying_class: "",
    parent_name: "",
    parent_phone: "",
    academic_year_id: "",
    academic_year: "",
  });
  const enquiryForm = useForm({ name: "", email: "", phone: "", message: "" });

  // Academic year options in "2026-27" format. Uses configured years (real UUID
  // ids) when available; otherwise falls back to a rolling window of text labels
  // that carry NO id, so only the readable label is persisted.
  const yearOptions = useMemo(() => {
    const configured = (years.data || []).map((y: any) => ({
      id: y.id,
      label: y.name,
      current: !!y.is_current,
    }));
    if (configured.length) return configured;
    const now = new Date().getFullYear();
    return Array.from({ length: 6 }, (_, i) => {
      const start = now - 2 + i;
      const label = `${start}-${String((start + 1) % 100).padStart(2, "0")}`;
      return { id: "", label, current: i === 2 };
    });
  }, [years.data]);

  const selectedYearOption = () => {
    if (appForm.values.academic_year_id) {
      return (
        yearOptions.find(
          (y: any) => y.id === appForm.values.academic_year_id,
        ) || {
          id: appForm.values.academic_year_id,
          label: appForm.values.academic_year || "",
        }
      );
    }
    return { id: "", label: appForm.values.academic_year || "" };
  };

  const refreshAll = () => {
    applications.refetch();
    enquiries.refetch();
    reports.refetch();
    years.refetch();
  };

  const filteredApplications = useMemo(() => {
    const q = search.toLowerCase().trim();
    return (applications.data || []).filter(
      (app: any) =>
        !q ||
        [
          app.applicant_name,
          app.applicant_email,
          app.phone,
          app.applying_class,
          app.parent_name,
        ].some((v) =>
          String(v || "")
            .toLowerCase()
            .includes(q),
        ),
    );
  }, [applications.data, search]);

  const filteredEnquiries = useMemo(() => {
    const q = search.toLowerCase().trim();
    return (enquiries.data || []).filter(
      (enquiry: any) =>
        !q ||
        [enquiry.name, enquiry.email, enquiry.phone, enquiry.message].some(
          (v) =>
            String(v || "")
              .toLowerCase()
              .includes(q),
        ),
    );
  }, [enquiries.data, search]);

  const handleCreateApplication = async () => {
    if (!appForm.values.applicant_name || !appForm.values.applying_class) {
      toast.error("Applicant name and class are required");
      return;
    }
    setSaving(true);
    try {
      const chosen = selectedYearOption();
      const isUuidYear =
        chosen.id &&
        /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
          chosen.id,
        );
      const res = await admissionApi.createApplication({
        ...appForm.values,
        academic_year_id: isUuidYear ? chosen.id : "",
        academic_year: chosen.label || appForm.values.academic_year || "",
      });
      if (!res.success) {
        toast.error(res.error || "Failed to create application");
        return;
      }
      toast.success("Admission application created");
      const defOpt = yearOptions.find((y: any) => y.current) ||
        yearOptions[0] || { id: "", label: "" };
      appForm.setValues({
        applicant_name: "",
        applicant_email: "",
        phone: "",
        applying_class: "",
        parent_name: "",
        parent_phone: "",
        academic_year_id: defOpt.id || "",
        academic_year: defOpt.label || "",
      });
      setModal(null);
      refreshAll();
    } finally {
      setSaving(false);
    }
  };

  const handleCreateEnquiry = async () => {
    if (!enquiryForm.values.name || !enquiryForm.values.phone) {
      toast.error("Name and phone are required");
      return;
    }
    setSaving(true);
    try {
      const res = await admissionApi.createEnquiry(enquiryForm.values);
      if (!res.success) {
        toast.error(res.error || "Failed to create enquiry");
        return;
      }
      toast.success("Admission enquiry created");
      enquiryForm.setValues({ name: "", email: "", phone: "", message: "" });
      setModal(null);
      refreshAll();
    } finally {
      setSaving(false);
    }
  };

  const updateStatus = async (id: string, status: string) => {
    const app = (applications.data || []).find((a: any) => a.id === id);
    const isApproved = app?.status === "approved";
    if ((status === "rejected" || status === "waitlisted") && isApproved) {
      const ok = window.confirm(
        `This application is currently approved. ${status === "rejected" ? "Rejecting" : "Waitlisting"} it will also remove the student from the admissions list. Continue?`,
      );
      if (!ok) return;
    }
    const res = await admissionApi.updateApplicationStatus(id, status);
    if (res.success) {
      toast.success(`Application ${status}`);
      refreshAll();
    } else {
      toast.error(res.error || "Failed to update status");
    }
  };

  const stats = reports.data || {};
  const appTotal = stats.totalApplications ?? applications.data?.length ?? 0;
  const pendingCount =
    stats.pending ??
    applications.data?.filter((a: any) => a.status === "pending").length ??
    0;
  const approvedCount =
    stats.approved ??
    applications.data?.filter((a: any) => a.status === "approved").length ??
    0;
  const enqTotal = stats.totalEnquiries ?? enquiries.data?.length ?? 0;
  const statCards = [
    {
      label: "Applications",
      value: appTotal,
      icon: FileText,
      color: "#6D4CFF",
      bg: "#F0EDFF",
    },
    {
      label: "Pending",
      value: pendingCount,
      icon: Clock,
      color: "#F59E0B",
      bg: "#FFFBEB",
    },
    {
      label: "Approved",
      value: approvedCount,
      icon: CheckCircle2,
      color: "#10B981",
      bg: "#ECFDF5",
    },
    {
      label: "Enquiries",
      value: enqTotal,
      icon: MessageSquare,
      color: "#3B82F6",
      bg: "#EFF6FF",
    },
  ];

  return (
    <div className="px-6 pb-6 space-y-5">
      <ModuleHeader
        icon={UserPlus}
        gradient="bg-gradient-to-br from-[#3B82F6] to-[#06B6D4]"
        title={t("nav.admissions")}
        subtitle="Manage admission applications, enquiries, and follow-up decisions"
        onRefresh={refreshAll}
      />
      <div className="flex flex-col sm:flex-row gap-2 justify-end">
        <button
          onClick={() => setModal("enquiry")}
          className="flex items-center justify-center gap-1.5 px-3 py-2 rounded-lg border border-gray-200 text-gray-600 text-xs font-semibold hover:bg-gray-50"
        >
          <MessageSquare size={14} /> New Enquiry
        </button>
        <AddButton
          onClick={() => setModal("application")}
          label="New Application"
        />
      </div>
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        {statCards.map((card) => (
          <div key={card.label} className="stat-card">
            <div
              className="w-9 h-9 rounded-xl flex items-center justify-center mb-2"
              style={{ background: card.bg, color: card.color }}
            >
              <card.icon size={18} />
            </div>
            <div className="text-[11px] text-gray-500 font-medium">
              {card.label}
            </div>
            <div className="text-xl font-extrabold text-gray-900 mt-0.5">
              {card.value}
            </div>
          </div>
        ))}
      </div>

      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-4">
        <div className="flex gap-1 p-1 bg-gray-100 rounded-xl w-fit">
          {[
            { key: "applications", label: "Applications" },
            { key: "enquiries", label: "Enquiries" },
          ].map((tab) => (
            <button
              key={tab.key}
              onClick={() => setView(tab.key as any)}
              className={`px-4 py-2 rounded-lg text-xs font-semibold transition-all ${view === tab.key ? "bg-white text-gray-900 shadow-sm" : "text-gray-500 hover:text-gray-700"}`}
            >
              {tab.label}
            </button>
          ))}
        </div>
        <div className="relative w-full sm:w-64">
          <Search
            size={14}
            className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
          />
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search admissions..."
            className="w-full pl-9 pr-3 py-2 border border-gray-200 rounded-lg text-xs focus:outline-none focus:border-[#6D4CFF]"
          />
        </div>
      </div>

      {view === "applications" ? (
        <DataTable
          columns={[
            {
              key: "applicant_name",
              label: "Applicant",
              render: (v: string, row: any) => (
                <div>
                  <div className="text-xs font-semibold">{v || "—"}</div>
                  <div className="text-[9px] text-gray-400">
                    {row.applicant_email || row.phone || "No contact"}
                  </div>
                </div>
              ),
            },
            { key: "applying_class", label: "Class" },
            {
              key: "academic_year",
              label: "Academic Year",
              render: (v: any, row: any) => (
                <span className="text-xs">
                  {row.academic_year ||
                    row.academic_year_info?.name ||
                    v ||
                    "—"}
                </span>
              ),
            },
            {
              key: "parent_name",
              label: "Parent",
              render: (v: string, row: any) => (
                <span className="text-xs">{v || row.parent_phone || "—"}</span>
              ),
            },
            {
              key: "status",
              label: "Status",
              render: (v: string) => (
                <Badge
                  variant={
                    v === "approved"
                      ? "success"
                      : v === "rejected"
                        ? "danger"
                        : "warning"
                  }
                  className="text-[9px] capitalize"
                >
                  {v || "pending"}
                </Badge>
              ),
            },
            {
              key: "created_at",
              label: "Date",
              render: (v: string) =>
                v ? new Date(v).toLocaleDateString() : "—",
            },
            {
              key: "id",
              label: "Actions",
              render: (id: string, row: any) => (
                <div className="flex gap-1">
                  {row.status !== "approved" && (
                    <button
                      onClick={() => updateStatus(id, "approved")}
                      className="px-2 py-1 rounded-lg bg-green-50 text-green-600 text-[9px] font-semibold"
                    >
                      Approve
                    </button>
                  )}
                  {row.status !== "waitlisted" && (
                    <button
                      onClick={() => updateStatus(id, "waitlisted")}
                      className="px-2 py-1 rounded-lg bg-amber-50 text-amber-600 text-[9px] font-semibold"
                    >
                      Waitlist
                    </button>
                  )}
                  {row.status !== "rejected" && (
                    <button
                      onClick={() => updateStatus(id, "rejected")}
                      className="px-2 py-1 rounded-lg bg-red-50 text-red-500 text-[9px] font-semibold"
                    >
                      Reject
                    </button>
                  )}
                </div>
              ),
            },
          ]}
          data={filteredApplications}
          loading={applications.loading}
          error={applications.error}
          onRetry={applications.refetch}
          emptyMessage="No admission applications yet"
        />
      ) : (
        <DataTable
          columns={[
            {
              key: "name",
              label: "Name",
              render: (v: string, row: any) => (
                <div>
                  <div className="text-xs font-semibold">{v || "—"}</div>
                  <div className="text-[9px] text-gray-400">
                    {row.email || row.phone || "No contact"}
                  </div>
                </div>
              ),
            },
            { key: "phone", label: "Phone" },
            {
              key: "message",
              label: "Message",
              render: (v: string) => (
                <span className="text-xs line-clamp-1">{v || "—"}</span>
              ),
            },
            {
              key: "created_at",
              label: "Date",
              render: (v: string) =>
                v ? new Date(v).toLocaleDateString() : "—",
            },
          ]}
          data={filteredEnquiries}
          loading={enquiries.loading}
          error={enquiries.error}
          onRetry={enquiries.refetch}
          emptyMessage="No admission enquiries yet"
        />
      )}

      <CrudModal
        open={modal === "application"}
        onClose={() => setModal(null)}
        title="New Admission Application"
      >
        <div className="space-y-3">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label className="text-xs font-semibold text-gray-700 mb-1 block">
                Applicant Name
              </label>
              <input
                value={appForm.values.applicant_name}
                onChange={(e) =>
                  appForm.handleChange("applicant_name", e.target.value)
                }
                className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm"
              />
            </div>
            <div>
              <label className="text-xs font-semibold text-gray-700 mb-1 block">
                Applying Class
              </label>
              <select
                value={appForm.values.applying_class}
                onChange={(e) =>
                  appForm.handleChange("applying_class", e.target.value)
                }
                className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm bg-white"
              >
                <option value="">Select Class</option>
                {(classes.data || []).map((cls: any) => (
                  <option key={cls.id || cls.name} value={cls.name}>
                    {cls.name}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="text-xs font-semibold text-gray-700 mb-1 block">
                Academic Year
              </label>
              <select
                value={appForm.values.academic_year}
                onChange={(e) => {
                  const label = e.target.value;
                  const opt = yearOptions.find((y: any) => y.label === label);
                  appForm.handleChange("academic_year", label);
                  appForm.handleChange("academic_year_id", opt?.id || "");
                }}
                className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm bg-white"
              >
                <option value="">Select Year</option>
                {yearOptions.map((y: any) => (
                  <option key={y.label} value={y.label}>
                    {y.label}
                    {y.current ? " (Current)" : ""}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="text-xs font-semibold text-gray-700 mb-1 block">
                Applicant Email
              </label>
              <input
                type="email"
                value={appForm.values.applicant_email}
                onChange={(e) =>
                  appForm.handleChange("applicant_email", e.target.value)
                }
                className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm"
              />
            </div>
            <div>
              <label className="text-xs font-semibold text-gray-700 mb-1 block">
                Phone
              </label>
              <input
                value={appForm.values.phone}
                onChange={(e) => appForm.handleChange("phone", e.target.value)}
                className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm"
              />
            </div>
            <div>
              <label className="text-xs font-semibold text-gray-700 mb-1 block">
                Parent Name
              </label>
              <input
                value={appForm.values.parent_name}
                onChange={(e) =>
                  appForm.handleChange("parent_name", e.target.value)
                }
                className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm"
              />
            </div>
            <div>
              <label className="text-xs font-semibold text-gray-700 mb-1 block">
                Parent Phone
              </label>
              <input
                value={appForm.values.parent_phone}
                onChange={(e) =>
                  appForm.handleChange("parent_phone", e.target.value)
                }
                className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm"
              />
            </div>
          </div>
          <button
            onClick={handleCreateApplication}
            disabled={saving}
            className="w-full py-2.5 rounded-lg bg-gradient-to-r from-[#6D4CFF] to-[#8B5CF6] text-white text-sm font-semibold disabled:opacity-50"
          >
            {saving ? "Saving..." : "Create Application"}
          </button>
        </div>
      </CrudModal>

      <CrudModal
        open={modal === "enquiry"}
        onClose={() => setModal(null)}
        title="New Admission Enquiry"
      >
        <div className="space-y-3">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label className="text-xs font-semibold text-gray-700 mb-1 block">
                Name
              </label>
              <input
                value={enquiryForm.values.name}
                onChange={(e) =>
                  enquiryForm.handleChange("name", e.target.value)
                }
                className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm"
              />
            </div>
            <div>
              <label className="text-xs font-semibold text-gray-700 mb-1 block">
                Phone
              </label>
              <input
                value={enquiryForm.values.phone}
                onChange={(e) =>
                  enquiryForm.handleChange("phone", e.target.value)
                }
                className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm"
              />
            </div>
            <div className="sm:col-span-2">
              <label className="text-xs font-semibold text-gray-700 mb-1 block">
                Email
              </label>
              <input
                type="email"
                value={enquiryForm.values.email}
                onChange={(e) =>
                  enquiryForm.handleChange("email", e.target.value)
                }
                className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm"
              />
            </div>
            <div className="sm:col-span-2">
              <label className="text-xs font-semibold text-gray-700 mb-1 block">
                Message
              </label>
              <textarea
                value={enquiryForm.values.message}
                onChange={(e) =>
                  enquiryForm.handleChange("message", e.target.value)
                }
                rows={3}
                className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm"
              />
            </div>
          </div>
          <button
            onClick={handleCreateEnquiry}
            disabled={saving}
            className="w-full py-2.5 rounded-lg bg-gradient-to-r from-[#6D4CFF] to-[#8B5CF6] text-white text-sm font-semibold disabled:opacity-50"
          >
            {saving ? "Saving..." : "Create Enquiry"}
          </button>
        </div>
      </CrudModal>
    </div>
  );
}

